INSERT INTO "knowledge_chunks" VALUES(1,1,0,'Tiêu chuẩn chẩn đoán đái tháo đường của Hiệp hội Đái tháo đường Hoa Kỳ (ADA) bao gồm: 1) Glucose huyết tương lúc đói (FPG) >= 126 mg/dL (7.0 mmol/L) sau ít nhất 8 giờ nhịn đói; 2) Chỉ số HbA1c >= 6.5% (48 mmol/mol) thực hiện bằng phương pháp chuẩn hóa NGSP; 3) Glucose huyết tương 2 giờ sau nghiệm pháp dung nạp 75g glucose đường uống (OGTT) >= 200 mg/dL (11.1 mmol/L); hoặc 4) Bệnh nhân có triệu chứng kinh điển của tăng đường huyết kèm glucose huyết tương ngẫu nhiên >= 200 mg/dL. Tiền đái tháo đường được định nghĩa khi FPG từ 100 đến 125 mg/dL (rối loạn đường huyết đói) hoặc HbA1c từ 5.7% đến 6.4%.','{"ti\u00eau": 0.05965499862718936, "chu\u1ea9n": 0.11930999725437871, "ch\u1ea9n": 0.05965499862718936, "\u0111o\u00e1n": 0.05965499862718936, "\u0111\u00e1i": 0.17896499588156806, "th\u00e1o": 0.17896499588156806, "\u0111\u01b0\u1eddng": 0.3579299917631361, "c\u1ee7a": 0.11930999725437871, "hi\u1ec7p": 0.05965499862718936, "h\u1ed9i": 0.05965499862718936, "hoa": 0.05965499862718936, "k\u1ef3": 0.05965499862718936, "ada": 0.05965499862718936, "bao": 0.05965499862718936, "g\u1ed3m": 0.05965499862718936, "1": 0.11930999725437871, "glucose": 0.23861999450875743, "huy\u1ebft": 0.2982749931359468, "t\u01b0\u01a1ng": 0.17896499588156806, "l\u00fac": 0.05965499862718936, "\u0111\u00f3i": 0.17896499588156806, "fpg": 0.11930999725437871, "126": 0.05965499862718936, "mg": 0.23861999450875743, "dl": 0.23861999450875743, "7": 0.11930999725437871, "0": 0.05965499862718936, "mmol": 0.17896499588156806, "l": 0.11930999725437871, "sau": 0.11930999725437871, "\u00edt": 0.05965499862718936, "nh\u1ea5t": 0.05965499862718936, "8": 0.05965499862718936, "gi\u1edd": 0.11930999725437871, "nh\u1ecbn": 0.05965499862718936, "2": 0.11930999725437871, "ch\u1ec9": 0.05965499862718936, "s\u1ed1": 0.05965499862718936, "hba1c": 0.11930999725437871, "6": 0.11930999725437871, "5": 0.11930999725437871, "48": 0.05965499862718936, "mol": 0.05965499862718936, "th\u1