INSERT INTO "knowledge_chunks" VALUES(2,2,0,'Tổ chức Y tế Thế giới (WHO) khuyến cáo lối sống lành mạnh là biện pháp can thiệp cốt lõi để phòng ngừa và kiểm soát đái tháo đường type 2. Khuyến nghị bao gồm: 1) Đạt và duy trì chỉ số khối cơ thể (BMI) khỏe mạnh từ 18.5 đến 22.9 kg/m2 đối với người châu Á; 2) Duy trì hoạt động thể lực đều đặn ít nhất 150 phút mỗi tuần với cường độ trung bình (đi bộ nhanh, chạy bộ, bơi lội); 3) Giảm thiểu lượng chất béo bão hòa dưới 10% tổng năng lượng khẩu phần; 4) Tăng cường hấp thụ chất xơ tối thiểu 20-35g mỗi ngày thông qua ngũ cốc nguyên hạt, các loại đậu và rau xanh tươi; 5) Giới hạn lượng đường tự do dưới 5% tổng năng lượng nạp vào.','{"t\u1ed5": 0.07053456158585983, "ch\u1ee9c": 0.07053456158585983, "y": 0.07053456158585983, "t\u1ebf": 0.07053456158585983, "th\u1ebf": 0.07053456158585983, "gi\u1edbi": 0.14106912317171966, "who": 0.07053456158585983, "khuy\u1ebfn": 0.14106912317171966, "c\u00e1o": 0.07053456158585983, "l\u1ed1i": 0.07053456158585983, "s\u1ed1ng": 0.07053456158585983, "l\u00e0nh": 0.07053456158585983, "m\u1ea1nh": 0.14106912317171966, "l\u00e0": 0.07053456158585983, "bi\u1ec7n": 0.07053456158585983, "ph\u00e1p": 0.07053456158585983, "can": 0.07053456158585983, "thi\u1ec7p": 0.07053456158585983, "c\u1ed1t": 0.07053456158585983, "l\u00f5i": 0.07053456158585983, "\u0111\u1ec3": 0.07053456158585983, "ph\u00f2ng": 0.07053456158585983, "ng\u1eeba": 0.07053456158585983, "v\u00e0": 0.21160368475757949, "ki\u1ec3m": 0.07053456158585983, "so\u00e1t": 0.07053456158585983, "\u0111\u00e1i": 0.07053456158585983, "th\u00e1o": 0.07053456158585983, "\u0111\u01b0\u1eddng": 0.14106912317171966, "type": 0.07053456158585983, "2": 0.14106912317171966, "ngh\u1ecb": 0.07053456158585983, "bao": 0.07053456158585983, "g\u1ed3m": 0.07053456158585983, "1": 0.07053456158585983, "\u0111\u1ea1t": 0.07053456158585983, "duy": 0.14106912317171966, "tr\u00ec": 0.14106912317171966, "ch\u1ec9": 0.07053456158585983, "s\u1ed1": 0.07053456158585983, "kh\u1