INSERT INTO "knowledge_chunks" VALUES(3,3,0,'Hạ đường huyết xảy ra khi nồng độ glucose trong máu giảm xuống dưới 70 mg/dL (3.9 mmol/L). Triệu chứng lâm sàng điển hình gồm: run rẩy, vã mồ hôi lạnh, tim đập nhanh, chóng mặt, đói cồn cào, nhìn mờ, lú lẫn và cáu gắt. Xử trí theo ''Quy tắc 15-15'': Nạp ngay 15 gam carbohydrate tác dụng nhanh (1/2 cốc nước ép trái cây, 1/2 lon nước ngọt thông thường hoặc 3-4 viên đường glucose). Nghỉ ngơi và kiểm tra lại đường huyết sau 15 phút. Nếu vẫn dưới 70 mg/dL, lặp lại thêm 15 gam đường. Khi bệnh nhân mất tri giác, co giật hoặc không thể nuốt, KHÔNG cho ăn uống qua đường miệng, tiêm glucagon nếu có và gọi cấp cứu 115 ngay lập tức.','{"h\u1ea1": 0.06741998624632421, "\u0111\u01b0\u1eddng": 0.337099931231621, "huy\u1ebft": 0.13483997249264842, "x\u1ea3y": 0.06741998624632421, "ra": 0.06741998624632421, "khi": 0.13483997249264842, "n\u1ed3ng": 0.06741998624632421, "\u0111\u1ed9": 0.06741998624632421, "glucose": 0.13483997249264842, "trong": 0.06741998624632421, "m\u00e1u": 0.06741998624632421, "gi\u1ea3m": 0.06741998624632421, "xu\u1ed1ng": 0.06741998624632421, "d\u01b0\u1edbi": 0.13483997249264842, "70": 0.13483997249264842, "mg": 0.13483997249264842, "dl": 0.13483997249264842, "3": 0.13483997249264842, "9": 0.06741998624632421, "mmol": 0.06741998624632421, "l": 0.06741998624632421, "tri\u1ec7u": 0.06741998624632421, "ch\u1ee9ng": 0.06741998624632421, "l\u00e2m": 0.06741998624632421, "s\u00e0ng": 0.06741998624632421, "\u0111i\u1ec3n": 0.06741998624632421, "h\u00ecnh": 0.06741998624632421, "g\u1ed3m": 0.06741998624632421, "run": 0.06741998624632421, "r\u1ea9y": 0.06741998624632421, "v\u00e3": 0.06741998624632421, "m\u1ed3": 0.06741998624632421, "h\u00f4i": 0.06741998624632421, "l\u1ea1nh": 0.06741998624632421, "tim": 0.06741998624632421, "\u0111\u1eadp": 0.06741998624632421, "nhanh": 0.13483997249264842, "ch\u00f3ng": 0.06741998624632421, "m\u1eb7t": 0.06741998624632421, "\u0111\u00f3i": 0.06741998624632421, "c\u1ed3n": 0.067419986246