2421, "c\u00f3": 0.06741998624632421, "g\u1ecdi": 0.06741998624632421, "c\u1ea5p": 0.06741998624632421, "c\u1ee9u": 0.06741998624632421, "115": 0.06741998624632421, "l\u1eadp": 0.06741998624632421, "t\u1ee9c": 0.06741998624632421}','2026-11-05 11:27:56.332832');
INSERT INTO "knowledge_chunks" VALUES(4,4,0,'Thừa cân béo phì (đặc biệt là tích tụ mỡ nội tạng) giải phóng các acid béo tự do và cytokine gây viêm (TNF-alpha, IL-6), làm suy giảm tín hiệu thụ thể insulin tại cơ vân và mô gan, dẫn đến tình trạng kháng insulin. Tăng huyết áp đi kèm làm gia tăng áp lực mạch máu, tổn thương nội mô và thúc đẩy biến chứng vi mạch ở cầu thận và võng mạc. Việc kiểm soát đồng thời chỉ số huyết áp dưới 130/80 mmHg và đưa BMI về ngưỡng tối ưu giúp giảm hơn 40% nguy cơ biến chứng tim mạch ở người có nguy cơ đái tháo đường.','{"th\u1eeba": 0.07537783614444091, "c\u00e2n": 0.07537783614444091, "b\u00e9o": 0.15075567228888181, "ph\u00ec": 0.07537783614444091, "\u0111\u1eb7c": 0.07537783614444091, "bi\u1ec7t": 0.07537783614444091, "l\u00e0": 0.07537783614444091, "t\u00edch": 0.07537783614444091, "t\u1ee5": 0.07537783614444091, "m\u1ee1": 0.07537783614444091, "n\u1ed9i": 0.15075567228888181, "t\u1ea1ng": 0.07537783614444091, "gi\u1ea3i": 0.07537783614444091, "ph\u00f3ng": 0.07537783614444091, "c\u00e1c": 0.07537783614444091, "acid": 0.07537783614444091, "t\u1ef1": 0.07537783614444091, "do": 0.07537783614444091, "v\u00e0": 0.3768891807222045, "cytokine": 0.07537783614444091, "g\u00e2y": 0.07537783614444091, "vi\u00eam": 0.07537783614444091, "tnf": 0.07537783614444091, "alpha": 0.07537783614444091, "il": 0.07537783614444091, "6": 0.07537783614444091, "l\u00e0m": 0.15075567228888181, "suy": 0.07537783614444091, "gi\u1ea3m": 0.15075567228888181, "t\u00edn": 0.07537783614444091, "hi\u1ec7u": 0.07537783614444091, "th\u1ee5": 0.07537783614444091, "th\u1ec3": 0.07537783614444091, "insulin": 0.15075567228888181, "t\u1ea1i": 0.07537783614444091, "c\u01a1": 0.22613350843332272, "v\u00e2n": 0.07537783614444091, "m\u00f4": 0.15075567228888181, "gan": 0.07537783614444091, "d\u1eabn": 0.07537783614444091, "\u0111\u1ebfn": 0.07537783614444091, "t\u00ecnh": 0.07537783614444091, "tr\u1ea1ng": 0.07537783614444091, "kh\u00e1ng": 0.07537783614444091, "t\u0103ng": 0.15075567228888181, "huy\u1ebft": 0.15075567228888181, "\u00e1p": 0.22613350843332272, "\u0111i": 0.07537783614444091, "k\u00e8m": 0.07537783614444091, "gia": 0.07537783614444091, "l\u1ef1c": 0.07537783614444091, "m\u1ea1ch": 0.22613350843332272, "m\u00e1u": 0.07537783614444091, "t\u1ed5n": 0.07537783614444091, "th\u01b0\u01a1ng": 0.07537783614444091, "th\u00fac": 0.07537783614444091, "\u0111\u1ea9y": 0.07537783614444091, "bi\u1ebfn": 0.15075567228888181, "ch\u1ee9ng": 0.15075567228888181, "vi": 0.07537783614444091, "\u1edf": 0.15075567228888181, "c\u1ea7u": 0.07537783614444091, "th\u1eadn": 0.07537783614444091, "v\u00f5ng": 0.07537783614444091, "m\u1ea1c": 0.07537783614444091, "vi\u1ec7c": 0.07537783614444091, "ki\u1ec3m": 0.07537783614444091, "so\u00e1t": 0.07537783614444091, "\u0111\u1ed3ng": 0.07537783614444091, "th\u1eddi": 0.07537783614444091, "ch\u1ec9": 0.07537783614444091, "s\u1ed1": 0.07537783614444091, "d\u01b0\u1edbi": 0.07537783614444091, "130": 0.07537783614444091, "80": 0.07537783614444091, "mmhg": 0.07537783614444091, "\u0111\u01b0a": 0.07537783614444091, "bmi": 0.07537783614444091, "v\u1ec1": 0.07537783614444091, "ng\u01b0\u1ee1ng": 0.07537783614444091, "t\u1ed1i": 0.07537783614444091, "\u01b0u": 0.07537783614444091, "gi\u00fap": 0.07537783614444091, "h\u01a1n": 0.07537783614444091, "40": 0.07537783614444091, "nguy": 0.15075567228888181, "tim": 0.07537783614444091, "ng\u01b0\u1eddi": 0.07537783614444091, "c\u00f3": 0.07537783614444091, "\u0111\u00e1i": 0.07537783614444091, "th\u00e1o": 0.07537783614444091, "\u0111\u01b0\u1eddng": 0.07537783614444091}','2026-11-05 11:27:56.344834');
