INSERT INTO "knowledge_documents" VALUES(1,'KB_ADA_001','Tiêu Chuẩn Chẩn Đoán & Phân Loại Đái Tháo Đường ADA','Diagnostic Tests','Hiệp hội Đái tháo đường Hoa Kỳ (ADA)','Tiêu chuẩn chẩn đoán đái tháo đường của Hiệp hội Đái tháo đường Hoa Kỳ (ADA) bao gồm: 1) Glucose huyết tương lúc đói (FPG) >= 126 mg/dL (7.0 mmol/L) sau ít nhất 8 giờ nhịn đói; 2) Chỉ số HbA1c >= 6.5% (48 mmol/mol) thực hiện bằng phương pháp chuẩn hóa NGSP; 3) Glucose huyết tương 2 giờ sau nghiệm pháp dung nạp 75g glucose đường uống (OGTT) >= 200 mg/dL (11.1 mmol/L); hoặc 4) Bệnh nhân có triệu chứng kinh điển của tăng đường huyết kèm glucose huyết tương ngẫu nhiên >= 200 mg/dL. Tiền đái tháo đường được định nghĩa khi FPG từ 100 đến 125 mg/dL (rối loạn đường huyết đói) hoặc HbA1c từ 5.7% đến 6.4%.',1,'2026-11-05 11:27:56.301714');
INSERT INTO "knowledge_documents" VALUES(2,'KB_WHO_002','Khuyến Nghị Dinh Dưỡng & Hoạt Động Thể Lực Phòng Ngừa Bệnh Đái Tháo Đường','Nutrition','Tổ chức Y tế Thế giới (WHO)','Tổ chức Y tế Thế giới (WHO) khuyến cáo lối sống lành mạnh là biện pháp can thiệp cốt lõi để phòng ngừa và kiểm soát đái tháo đường type 2. Khuyến nghị bao gồm: 1) Đạt và duy trì chỉ số khối cơ thể (BMI) khỏe mạnh từ 18.5 đến 22.9 kg/m2 đối với người châu Á; 2) Duy trì hoạt động thể lực đều đặn ít nhất 150 phút mỗi tuần với cường độ trung bình (đi bộ nhanh, chạy bộ, bơi lội); 3) Giảm thiểu lượng chất béo bão hòa dưới 10% tổng năng lượng khẩu phần; 4) Tăng cường hấp thụ chất xơ tối thiểu 20-35g mỗi ngày thông qua ngũ cốc nguyên hạt, các loại đậu và rau xanh tươi; 5) Giới hạn lượng đường tự do dưới 5% tổng năng lượng nạp vào.',1,'2026-11-05 11:27:56.314718');
INSERT INTO "knowledge_documents" VALUES(3,'KB_CDC_003','Hướng Dẫn Nhận Diện & Xử Trí Khẩn Cấp Hạ Đường Huyết (Hypoglycemia)','Symptoms','Trung tâm Kiểm soát và Phòng ngừa Dịch bệnh Hoa Kỳ (CDC)','Hạ đường huyết xảy ra khi nồng độ glucose trong máu giảm xuống dưới 70 mg/dL (3.9 mmol/L). Triệu chứng lâm sàng điển hình gồm: run rẩy, vã mồ hôi lạnh, tim đập nhanh, chóng mặt, đói cồn cào, nhìn mờ, lú lẫn và cáu gắt. Xử trí theo ''Quy tắc 15-15'': Nạp ngay 15 gam carbohydrate tác dụng nhanh (1/2 cốc nước ép trái cây, 1/2 lon nước ngọt thông thường hoặc 3-4 viên đường glucose). Nghỉ ngơi và kiểm tra lại đường huyết sau 15 phút. Nếu vẫn dưới 70 mg/dL, lặp lại thêm 15 gam đường. Khi bệnh nhân mất tri giác, co giật hoặc không thể nuốt, KHÔNG cho ăn uống qua đường miệng, tiêm glucagon nếu có và gọi cấp cứu 115 ngay lập tức.',1,'2026-11-05 11:27:56.326835');
INSERT INTO "knowledge_documents" VALUES(4,'KB_NIDDK_004','Mối Liên Hệ Giữa Chỉ Số Khối Cơ Thể BMI, Tăng Huyết Áp và Kháng Insulin','Risk Factors','Viện Quốc gia về Bệnh Tiểu đường, Tiêu hóa và Bệnh Thận (NIDDK)','Thừa cân béo phì (đặc biệt là tích tụ mỡ nội tạng) giải phóng các acid béo tự do và cytokine gây viêm (TNF-alpha, IL-6), làm suy giảm tín hiệu thụ thể insulin tại cơ vân và mô gan, dẫn đến tình trạng kháng insulin. Tăng huyết áp đi kèm làm gia tăng áp lực mạch máu, tổn thương nội mô và thúc đẩy biến chứng vi mạch ở cầu thận và võng mạc. Việc kiểm soát đồng thời chỉ số huyết áp dưới 130/80 mmHg và đưa BMI về ngưỡng tối ưu giúp giảm hơn 40% nguy cơ biến chứng tim mạch ở người có nguy cơ đái tháo đường.',1,'2026-11-05 11:27:56.338834');
