CREATE TABLE rule_execution_logs (
	id INTEGER NOT NULL, 
	rule_id VARCHAR(100) NOT NULL, 
	user_id INTEGER, 
	triggered BOOLEAN, 
	input_data_json JSON, 
	result_json JSON, 
	executed_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE rules (
	id INTEGER NOT NULL, 
	rule_id VARCHAR(100) NOT NULL, 
	rule_name VARCHAR(255) NOT NULL, 
	category VARCHAR(50) NOT NULL, 
	description TEXT NOT NULL, 
	conditions_json JSON NOT NULL, 
	actions_json JSON NOT NULL, 
	priority INTEGER, 
	is_enabled BOOLEAN, 
	is_immutable BOOLEAN, 
	version VARCHAR(20), 
	PRIMARY KEY (id)
);
INSERT INTO "rules" VALUES(1,'RULE_SAFE_001','Emergency Hypoglycemia Detection','safety','Trigger urgent alert when blood glucose is below 70 mg/dL (severe risk of hypoglycemia shock).','{"field": "blood_glucose_level", "operator": "<", "value": 70.0}','{"severity": "EMERGENCY", "action": "TRIGGER_ALERT", "message": "C\u1ea2NH B\u00c1O KH\u1ea8N C\u1ea4P: \u0110\u01b0\u1eddng huy\u1ebft d\u01b0\u1edbi 70 mg/dL (H\u1ea1 \u0111\u01b0\u1eddng huy\u1ebft). H\u00e3y n\u1ea1p ngay 15g carbohydrate t\u00e1c d\u1ee5ng nhanh (1/2 ly n\u01b0\u1edbc tr\u00e1i c\u00e2y ho\u1eb7c 3-4 vi\u00ean \u0111\u01b0\u1eddng) v\u00e0 ki\u1ec3m tra l\u1ea1i sau 15 ph\u00fat. N\u1ebfu h\u00f4n m\u00ea ho\u1eb7c l\u00fa l\u1eabn, g\u1ecdi c\u1ea5p c\u1ee9u 115 ngay l\u1eadp t\u1ee9c!"}',1,1,1,'1.0.0');
INSERT INTO "rules" VALUES(2,'RULE_SAFE_002','Emergency Hyperglycemia / Ketoacidosis Warning','safety','Trigger urgent alert when blood glucose exceeds 250 mg/dL (risk of DKA or HHS).','{"field": "blood_glucose_level", "operator": ">=", "value": 250.0}','{"severity": "EMERGENCY", "action": "TRIGGER_ALERT", "message": "C\u1ea2NH B\u00c1O NGUY HI\u1ec2M: \u0110\u01b0\u1eddng huy\u1ebft r\u1ea5t cao (>= 250 mg/dL). Nguy c\u01a1 nhi\u1ec5m toan ceton \u0111\u00e1i th\u00e1o \u0111\u01b0\u1eddng (DKA) ho\u1eb7c t\u0103ng \u00e1p l\u1ef1c th\u1ea9m th\u1ea5u. H\u00e3y u\u1ed1ng nhi\u1ec1u n\u01b0\u1edbc, ki\u1ec3m tra ceton ni\u1ec7u v\u00e0 \u0111\u1ebfn ngay c\u01a1 s\u1edf y t\u1ebf g\u1ea7n nh\u1ea5t!"}',1,1,1,'1.0.0');
INSERT INTO "rules" VALUES(3,'RULE_MON_001','ADA Fasting Glucose Diagnostic Screening','monitoring','Evaluate fasting blood glucose threshold based on ADA clinical standards.','{"field": "blood_glucose_level", "operator": ">=", "value": 126.0}','{"severity": "WARNING", "action": "NOTIFY", "message": "\u0110\u01b0\u1eddng huy\u1ebft \u0111\u00f3i >= 126 mg/dL n\u1eb1m trong ng\u01b0\u1ee1ng ch\u1ea9n \u0111o\u00e1n \u0111\u00e1i th\u00e1o \u0111\u01b0\u1eddng c\u1ee7a Hi\u1ec7p h\u1ed9i \u0110\u00e1i th\u00e1o \u0111\u01b0\u1eddng Hoa K\u1ef3 (ADA). C\u1ea7n l\u00e0m x\u00e9t nghi\u1ec7m l\u1eb7p l\u1ea1i \u0111\u1ec3 x\u00e1c nh\u1eadn."}',3,1,0,'1.0.0');
INSERT INTO "rules" VALUES(4,'RULE_MON_002','ADA HbA1c Diabetic Threshold','monitoring','Evaluate HbA1c >= 6.5% standard.','{"field": "HbA1c_level", "operator": ">=", "value": 6.5}','{"severity": "WARNING", "action": "NOTIFY", "message": "Ch\u1ec9 s\u1ed1 HbA1c >= 6.5% ph\u1ea3n \u00e1nh n\u1ed3ng \u0111\u1ed9 \u0111\u01b0\u1eddng huy\u1ebft trung b\u00ecnh 3 th\u00e1ng qua \u1edf ng\u01b0\u1ee1ng \u0111\u00e1i th\u00e1o \u0111\u01b0\u1eddng. Khuy\u1ebfn ngh\u1ecb th\u0103m kh\u00e1m b\u00e1c s\u0129 chuy\u00ean khoa n\u1ed9i ti\u1ebft."}',3,1,0,'1.0.0');
INSERT INTO "rules" VALUES(5,'RULE_MON_003','ADA Impaired Fasting Glucose (Prediabetes)','monitoring','Detect prediabetes fasting glucose 100 - 125 mg/dL.','{"field": "blood_glucose_level", "operator": "range", "min": 100.0, "max": 125.0}','{"severity": "INFO", "action": "NOTIFY", "message": "Ch\u1ec9 s\u1ed1 \u0111\u01b0\u1eddng huy\u1ebft \u0111\u00f3i 100-125 mg/dL thu\u1ed9c m\u1ee9c ti\u1ec1n \u0111\u00e1i th\u00e1o \u0111\u01b0\u1eddng (R\u1ed1i lo\u1ea1n dung n\u1ea1p \u0111\u01b0\u1eddng huy\u1ebft \u0111\u00f3i). Thay \u0111\u1ed5i l\u1ed1i s\u1ed1ng v\u00e0 dinh d\u01b0\u1ee1ng c\u00f3 th\u1ec3 \u0111\u1ea9y l\u00f9i ti\u1ebfn tri\u1ec3n th\u00e0nh b\u1ec7nh."}',5,1,0,'1.0.0');
INSERT INTO "rules" VALUES(6,'RULE_SAFE_PRESCRIPTION','Block Prohibited Medication Prescription','safety','Strictly block any agent or LLM from prescribing drug dosages (e.g. insulin units, metformin milligrams).','{"field": "response_text", "operator": "regex", "pattern": "(u\u1ed1ng|ti\u00eam|d\u00f9ng|li\u1ec1u)\\s+\\d+\\s*(vi\u00ean|mg|\u0111\u01a1n v\u1ecb|units|ml)"}','{"severity": "CRITICAL", "action": "BLOCK_RESPONSE", "message": "H\u1ec7 th\u1ed1ng AI t\u1eeb ch\u1ed1i ch\u1ec9 \u0111\u1ecbnh \u0111\u01a1n thu\u1ed1c ho\u1eb7c \u0111i\u1ec1u ch\u1ec9nh li\u1ec1u l\u01b0\u1ee3ng thu\u1ed1c. Vi\u1ec7c k\u00ea \u0111\u01a1n ch\u1ec9 \u0111\u01b0\u1ee3c th\u1ef1c hi\u1ec7n b\u1edfi b\u00e1c s\u0129 \u0111i\u1ec1u tr\u1ecb c\u00f3 ch\u1ee9ng ch\u1ec9 h\u00e0nh ngh\u1ec1."}',1,1,1,'1.0.0');
CREATE TABLE users (
	id INTEGER NOT NULL, 
	email VARCHAR(255) NOT NULL, 
	hashed_password VARCHAR(255) NOT NULL, 
	full_name VARCHAR(255) NOT NULL, 
	role VARCHAR(50), 
	is_active BOOLEAN, 
	created_at DATETIME, 
	PRIMARY KEY (id)
);
